821: pub fn first_terminal_crossing(
822:     structural_minutes: &[StrategicMinute],
823:     mut state_at: impl FnMut(StrategicMinute) -> MeterVector,
824: ) -> Option<(StrategicMinute, Meter)> {
825:     let mut points = structural_minutes.to_vec();
826:     points.sort_unstable();
827:     points.dedup();
828:     for window in points.windows(2) {
829:         let (mut left, mut right) = (window[0], window[1]);
830:         if let Some(meter) = state_at(left).terminal() {
831:             return Some((left, meter));
832:         }
833:         if state_at(right).terminal().is_none() {
834:             continue;
835:         }
836:         while right.elapsed_since(left) > 1 {
837:             let middle = left.midpoint(right);
838:             if state_at(middle).terminal().is_some() {
839:                 right = middle;
840:             } else {
841:                 left = middle;
842:             }
843:         }
844:         if let Some(meter) = state_at(right).terminal() {
845:             return Some((right, meter));
846:         }
847:     }
848:     None
849: }
